        {
                if (n >= 5)
                        return -1;
                int from = Str_parseInt(yytoken);
                int to = Str_parseInt(strchr(yytoken, '-') + 1);
                if ((fields[n] <= to) && (fields[n] >= from))
                        found++;
                n++;
                goto parse;
         }
