bool Time_backoff(bool predicate(void *args), void *args) {
        for (int i = 0, steps = 10; i < steps; i++) {
                if (predicate(args))
                        return true;
                _backoff(i);
        }
        return false;
}


static inline long long _usleep(long long microseconds, bool complete) {
        struct timespec req, rem;
        req.tv_sec = microseconds / 1000000LL;
        req.tv_nsec = (microseconds % 1000000LL) * 1000LL;
        while (nanosleep(&req, &rem) == -1) {
                if (! complete) {
                        if (errno == EINTR)
                                return rem.tv_sec * 1000000LL + rem.tv_nsec / 1000LL;
                }
                if (errno == EINVAL)
                        return -1;
                req = rem;
        }
        return 0;
}


long long Time_usleep(long long microseconds) {
        return _usleep(microseconds, false);
}


bool Time_usleepComplete(long long microseconds) {
        return _usleep(microseconds, true) == 0;
}


static inline long _sleep(long seconds, bool complete) {
        struct timespec req, rem;
        req.tv_sec = seconds;
        req.tv_nsec = 0;
        while (nanosleep(&req, &rem) == -1) {
                if (!complete) {
                        if (errno == EINTR)
                                return rem.tv_sec;
                }
                if (errno == EINVAL)
                        return -1;
                req = rem;
        }
        return 0;
}


long Time_sleep(long seconds) {
        return _sleep(seconds, false);
}


bool Time_sleepComplete(long seconds) {
        return _sleep(seconds, true) == 0;
}
